SELECT create_hypertable('observations', 'time', chunk_time_interval => INTERVAL '7 days');

-- Compression is configured at creation, not retrofitted (D-7). Segmenting by the
-- partition column and ordering by descending time is what the measured 11.2x ratio
-- was measured with.
ALTER TABLE observations SET (
    timescaledb.compress,
    timescaledb.compress_segmentby = 'station_id',
    timescaledb.compress_orderby   = 'time DESC'
);
SELECT add_compression_policy('observations', INTERVAL '7 days');

-- No retention policy, deliberately (D-4). Raw readings are retained indefinitely;
-- that is what makes the aggregates disposable derived data and adding a metric
-- cheap. Production's 365-day policy is the direct cause of the ~294 days that now
-- exist only as rollups.

-- Indexes beyond the hypertable's own time index are W4's (query shapes, not
-- metric definitions), so none is generated here.

