-- observations_1m: 1 minute buckets, read from the raw hypertable.
--
-- Three properties of this file are not negotiable, are easy to get wrong, and are
-- silent when wrong. They are properties of the generator's template, not of
-- whoever called it:
--
--   * sums accumulate in double precision, never in the column's own type. `sum(real)`
--     returns `real`, float4 addition is not associative, and a hierarchy therefore
--     adds in a different order than a direct scan — measured wrong in 55 of 56
--     uneven-bucket pairs, bit-identical in 56 of 56 once widened (D-14).
--   * counts are nulled at zero. `count()` returns 0 and never NULL, so on a
--     70%-NULL table a plain count column is fully populated and almost entirely
--     zeroes — 347 MB against 234 MB on a 398-column month (D-16).
--   * no column holds a finished average, and this level reads raw rather than raw.
--     `avg(avg(x))` was wrong in 658 of 868 real pairs and in all 56 uneven ones
--     (D-11, D-12). Means are finalised at query time by mw_mean().
--
-- Refresh policy, compression and retention for this view are W4's (OQ-4) and are
-- deliberately not generated here.

CREATE MATERIALIZED VIEW observations_1m
WITH (timescaledb.continuous, timescaledb.materialized_only = true) AS
SELECT
    time_bucket(INTERVAL '1 minute', time) AS bucket,
    station_id,
    -- Pressure [barometer]
    sum(barometer::double precision) AS barometer_sum,
    nullif(count(barometer), 0) AS barometer_count,
    min(barometer) AS barometer_min,
    max(barometer) AS barometer_max,
    -- Indoor temperature [in_temp]
